from functools import cache

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        @cache
        def d(i, j):
            if not i or not j:
                return i + j
            if word1[i - 1] == word2[j - 1]:
                return d(i - 1, j - 1)
            return 1 + min(d(i - 1, j), d(i, j - 1), d(i - 1, j - 1))
        return d(len(word1), len(word2))

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        dp = list(range(n + 1))             # 第 0 行：空串变成 word2[:j] 要插入 j 次
        for i in range(1, m + 1):
            leftup, dp[0] = dp[0], i        # 先存下左上角；第 0 列是 i（删光）
            for j in range(1, n + 1):
                up = dp[j]                  # 还没更新，是上一行的值
                if word1[i - 1] == word2[j - 1]:
                    dp[j] = leftup          # 最后一个字符相同，不用动
                else:
                    dp[j] = 1 + min(up, dp[j - 1], leftup)  # 删除、插入、替换
                leftup = up                 # 下一格的左上角，就是这一格的上面
        return dp[n]

